mapper.select:
SELECT EXISTS (
    SELECT 1 FROM settings_models
    WHERE name = #{name}

        AND id != #{modelId}
        AND EXISTS (SELECT 1 FROM settings_models WHERE id = #{modelId})

)

mapper.update:
UPDATE settings_models
id = id, name = #{name}, protocol = #{protocol}, provider = #{provider}, base_url = #{baseUrl}, model = #{model}, key = #{key},
WHERE id = #{id}
